<h1>Coupons</h1>
<div class="card"><form method="post" action="/admin/coupons/save" class="row"><?= csrf_field() ?><input name="code" placeholder="CODE" required><select name="type"><option value="percent">percent</option><option value="fixed">fixed</option></select><input name="value" type="number" step="0.01" placeholder="Value" required><input name="min_subtotal" type="number" step="0.01" placeholder="Min subtotal"><input name="expires_at" type="date"><button class="btn">Create</button></form></div>
<div class="tbl"><table><tr><th>Code</th><th>Type</th><th>Value</th><th>Used</th><th>Status</th></tr><?php foreach ($items as $c): ?><tr><td class="mono"><?= e($c['code']) ?></td><td><?= e($c['type']) ?></td><td><?= e($c['value']) ?></td><td><?= (int)$c['used_count'] ?></td><td><?= e($c['status']) ?></td></tr><?php endforeach; ?></table></div>
